pub struct PersistentReceiving<T:DslOwnedReceivingField+Sync>{source:OwnedSlot<FieldValue>,current:OwnedSlot<FieldValue>,row:OwnedSlot<T>,sealed:OwnedSlot<SealedShared<T>>,output:OwnedSlot<PersistentList<T>>,allocation:semio_framework_value::native_decoding::NativeSharedAdmission<T>,child:OwnedReceivingSlot<T>,builder:ManuallyDrop<Option<PersistentListBuilder<T>>>,index:usize,length:usize,phase:u8,closing:bool,failed:bool}
impl<T:DslOwnedReceivingField+Sync>Default for PersistentReceiving<T>{fn default()->Self{Self{source:Default::default(),current:Default::default(),row:Default::default(),sealed:Default::default(),output:Default::default(),allocation:Default::default(),child:OwnedReceivingSlot::new(),builder:ManuallyDrop::new(None),index:0,length:0,phase:0,closing:false,failed:false}}}
impl<T:DslOwnedReceivingField+Sync>DslOwnedReceivingField for PersistentList<T>{type Cursor=PersistentReceiving<T>;fn receiving_cursor()->Self::Cursor{Self::Cursor::default()}}
impl<T:DslOwnedReceivingField+Sync>PersistentReceiving<T>{
 pub fn shared_admission(&mut self)->&mut semio_framework_value::native_decoding::NativeSharedAdmission<T>{&mut self.allocation}
 fn builder(&self)->Result<&PersistentListBuilder<T>,ValueError>{self.builder.as_ref().ok_or_else(invariant)}
 fn selected(&mut self,input:&mut Option<FieldValue>,native:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneProgress,OriginalReceivingPrimary>{
  if self.closing||self.failed{return RetainedWorkOutcome{result:Err(invariant().into()),work:0}}if self.phase==11{return RetainedWorkOutcome{result:Ok(Default::default()),work:0}}let d=match self.demands(input,body){Ok(d)=>d,Err(error)=>return RetainedWorkOutcome{result:Err(error.into()),work:0}};if !funds(g,d){return RetainedWorkOutcome{result:Ok(Default::default()),work:0}}
  match self.phase{
   1 if self.builder.as_ref().is_some_and(|builder|!builder.accepts_row())=>{if let Err(error)=storage::capacity(native,d.capacity_bytes){return RetainedWorkOutcome{result:Err(error.into()),work:0}}let turn=self.builder.as_mut().unwrap().advance(g);return physical(native.receive_retained_work(g,turn))},
   1 if self.index==self.length=>{let turn=self.builder.as_mut().unwrap().finish(g);let result=turn.result.map(|progress|{if progress.is_some(){self.phase=7}progress.unwrap_or_default()});return RetainedWorkOutcome{result:result.map_err(Into::into),work:turn.work}},
   2 if !self.child.is_ready()=>return self.child.step(&mut self.current.value,native,body,child_grant(g)),
   3 if self.row.value.is_none()=>return normal(self.child.take_into(&mut self.row.value,child_grant(g))),
   4 if !self.child.terminal_is_empty()=>return post_child_close(self.child.close_step(child_grant(g)),native,g),
   5 if !self.allocation.can_advance()=>return RetainedWorkOutcome{result:Err(invariant().into()),work:0},
   5 if self.sealed.value.is_none()=>return native.receive_shared(&mut self.row.value,&mut self.sealed.value,semio_framework_value::shared_issuance::SharedIssuer::owned(),&mut self.allocation),
   6=>{let turn=self.builder.as_mut().unwrap().adopt(&mut self.sealed.value,g);let result=turn.result.map(|progress|{if progress.is_some(){self.index+=1;self.child=OwnedReceivingSlot::new();self.phase=1}progress.unwrap_or_default()});return RetainedWorkOutcome{result:result.map_err(Into::into),work:turn.work}},
   7 if !self.builder.as_ref().is_some_and(PersistentListBuilder::output_ready)=>{if let Err(error)=storage::capacity(native,d.capacity_bytes){return RetainedWorkOutcome{result:Err(error.into()),work:0}}let turn=self.builder.as_mut().unwrap().advance(g);return physical(native.receive_retained_work(g,turn))},
   8=>{let turn=self.builder.as_mut().unwrap().take(g);let result=turn.result.map(|output|if let Some((output,progress))=output{*self.output.value=Some(output);self.builder.as_mut().unwrap().begin_close();self.phase=9;progress}else{Default::default()});return RetainedWorkOutcome{result:result.map_err(Into::into),work:turn.work}},
   9 if self.builder.as_ref().is_some_and(|builder|!builder.terminal_is_empty())=>{let turn=self.builder.as_mut().unwrap().close_step(g);return physical(native.receive_retained_work(g,turn))},
   10 if !self.source.terminal_is_empty()=>return close_source(&mut self.source,native,g),_=>{}
  }
  if let Err(error)=native.checkpoint(){return RetainedWorkOutcome{result:Err(error.into()),work:0}}let result=(||{match self.phase{
   0=>{self.length=match input.as_ref(){Some(FieldValue::List(rows)|FieldValue::Tuple(rows))=>rows.len(),_=>return Err(invalid())};*self.source.value=input.take();*self.builder=Some(PersistentListBuilder::new(self.length));self.phase=1;},
   1=>{let Some(FieldValue::List(rows)|FieldValue::Tuple(rows))=self.source.value.as_mut()else{return Err(invariant())};*self.current.value=Some(std::mem::replace(rows.get_mut(self.index).ok_or_else(invariant)?,FieldValue::Absent));self.phase=2;},
   2=>self.phase=3,3=>self.phase=4,4=>self.phase=5,5=>self.phase=6,7=>self.phase=8,
   9=>{self.builder.take();self.phase=10;},10=>self.phase=11,_=>return Err(invariant())}Ok(receipt(d))})();RetainedWorkOutcome{result:result.map_err(|error|OriginalReceivingPrimary::from(error.with_retained_progress(receipt(metadata::<()>())))),work:1}
 }
}
impl<T:DslOwnedReceivingField+Sync>OwnedFieldReceiving<PersistentList<T>>for PersistentReceiving<T>{
 fn demands(&self,_:&Option<FieldValue>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.failed{return Err(invariant())}match self.phase{
  1 if !self.builder()?.accepts_row()=>self.builder()?.demand(),1 if self.index==self.length=>self.builder()?.finish_demand(),
  2 if !self.child.is_ready()=>self.child.demands(&self.current.value,body).and_then(nested),3 if self.row.value.is_none()=>nested(nested(metadata::<T>())?),4 if !self.child.terminal_is_empty()=>self.child.close_demands(body).and_then(nested),
  5 if self.sealed.value.is_none()=>Ok(self.allocation.shared_demand()),6=>self.builder()?.adopt_demand(),7 if !self.builder()?.output_ready()=>self.builder()?.demand(),8=>self.builder()?.take_demand(),9 if !self.builder()?.terminal_is_empty()=>self.builder()?.close_demand(body),10 if !self.source.terminal_is_empty()=>self.source.close_demands(body),11=>Ok(Default::default()),_=>Ok(metadata::<()>())}}
 fn step(&mut self,input:&mut Option<FieldValue>,native:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneProgress,OriginalReceivingPrimary>{let turn=self.selected(input,native,body,g);if turn.result.is_err()&&turn.work>0{self.failed=true}turn}
 fn is_ready(&self)->bool{!self.closing&&!self.failed&&self.phase==11&&self.output.value.is_some()}
 fn take_into(&mut self,output:&mut Option<PersistentList<T>>,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneProgress>{if !self.is_ready(){return RetainedWorkOutcome{result:Err(invariant()),work:0}}move_into(&mut self.output.value,output,g)}
  fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.allocation.phase()!=semio_framework_value::native_decoding::NativeReceivingEffectPhase::Empty{return Err(invariant())}if self.allocation.has_birth(){return self.allocation.close_demand()}if self.terminal_is_empty(){return Ok(Default::default())}if !self.closing{return Ok(metadata::<()>())}if !self.child.terminal_is_empty(){return self.child.close_demands(body).and_then(nested)}if !self.current.terminal_is_empty(){return self.current.close_demands(body)}if !self.row.terminal_is_empty(){return self.row.close_demands(body)}if !self.sealed.terminal_is_empty(){return self.sealed.close_demands(body)}if let Some(builder)=self.builder.as_ref(){if !builder.terminal_is_empty(){return builder.close_demand(body)}return Ok(metadata::<()>())}if !self.output.terminal_is_empty(){return self.output.close_demands(body)}self.source.close_demands(body)}
 fn close_step(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneProgress>{if self.terminal_is_empty(){return RetainedWorkOutcome{result:Ok(Default::default()),work:0}}let d=match self.close_demands(g.maximum_copy_bytes){Ok(d)=>d,Err(error)=>return RetainedWorkOutcome{result:Err(error),work:0}};if !funds(g,d){return RetainedWorkOutcome{result:Ok(Default::default()),work:0}}if self.allocation.has_birth(){let turn=self.allocation.close_step(g);return RetainedWorkOutcome{result:turn.result.map(|step|step.progress()),work:turn.work}}if !self.closing{self.closing=true;if let Some(builder)=self.builder.as_mut(){builder.begin_close()}return RetainedWorkOutcome{result:Ok(receipt(d)),work:1}}if !self.child.terminal_is_empty(){return self.child.close_step(child_grant(g))}if !self.current.terminal_is_empty(){return self.current.close_step(g)}if !self.row.terminal_is_empty(){return self.row.close_step(g)}if !self.sealed.terminal_is_empty(){return self.sealed.close_step(g)}if let Some(builder)=self.builder.as_mut(){if !builder.terminal_is_empty(){return physical(builder.close_step(g))}self.builder.take();return RetainedWorkOutcome{result:Ok(receipt(d)),work:1}}if !self.output.terminal_is_empty(){return self.output.close_step(g)}self.source.close_step(g)}
  fn terminal_is_empty(&self)->bool{self.allocation.terminal_is_empty()&&self.child.terminal_is_empty()&&self.current.terminal_is_empty()&&self.row.terminal_is_empty()&&self.sealed.terminal_is_empty()&&self.builder.is_none()&&self.output.terminal_is_empty()&&self.source.terminal_is_empty()}
}
impl<T:DslOwnedReceivingField+Sync>Drop for PersistentReceiving<T>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"persistent field receiving retains original row and page custody");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.builder)}}}}
